-- Final SQLite schema of the game database, as created by the last SQLite
-- build (database::create_tables). Used to test the PostgreSQL port and the
-- SQLite -> PostgreSQL copy tool. Do not edit.
CREATE TABLE credentials (username TEXT PRIMARY KEY, login_id TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE auth_tickets (token_hash TEXT PRIMARY KEY, login_id TEXT NOT NULL, kind TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE account_claims (code_hash TEXT PRIMARY KEY, login_id TEXT NOT NULL UNIQUE, expires_at INTEGER NOT NULL);
CREATE TABLE auth_attempts (username TEXT PRIMARY KEY, attempts INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE INDEX auth_ticket_expiry ON auth_tickets(expires_at);
CREATE TABLE coupon_redemptions(account_id INTEGER NOT NULL REFERENCES accounts(account_id),code TEXT NOT NULL,mail_id INTEGER NOT NULL,redeemed_at TEXT NOT NULL DEFAULT(datetime('now')),PRIMARY KEY(account_id,code));
CREATE TABLE accounts (
            account_id INTEGER PRIMARY KEY AUTOINCREMENT,
            login_id TEXT UNIQUE NOT NULL,
            login_method INTEGER NOT NULL DEFAULT 0,
            device_id TEXT,
            nick TEXT,
            created_at TEXT NOT NULL DEFAULT (datetime('now')),
            last_login TEXT,
            session_key TEXT,
            aes_key TEXT,
            country_code TEXT DEFAULT 'US',
            is_banned INTEGER NOT NULL DEFAULT 0
        , last_logout TEXT);
CREATE TABLE user_info (
            account_id INTEGER PRIMARY KEY,
            gold INTEGER NOT NULL DEFAULT 0,
            gem INTEGER NOT NULL DEFAULT 0,
            pay_gem INTEGER NOT NULL DEFAULT 0,
            pvp_coin INTEGER NOT NULL DEFAULT 0,
            stamina INTEGER NOT NULL DEFAULT 200,
            stamina_recharge_time INTEGER NOT NULL DEFAULT 0,
            team_level INTEGER NOT NULL DEFAULT 1,
            team_exp INTEGER NOT NULL DEFAULT 0,
            sword INTEGER NOT NULL DEFAULT 5,
            sword_recharge_time INTEGER NOT NULL DEFAULT 0,
            sword2 INTEGER NOT NULL DEFAULT 0,
            avatar_hero_index INTEGER NOT NULL DEFAULT 0,
            royal_point INTEGER NOT NULL DEFAULT 0,
            raid_point INTEGER NOT NULL DEFAULT 0,
            mileage INTEGER NOT NULL DEFAULT 0,
            friendship_point INTEGER NOT NULL DEFAULT 0,
            guild_raid_ticket INTEGER NOT NULL DEFAULT 0,
            world_boss_ticket INTEGER NOT NULL DEFAULT 0, event_dungeon_point INTEGER NOT NULL DEFAULT 0,
            FOREIGN KEY (account_id) REFERENCES accounts(account_id)
        );
CREATE TABLE heroes (
            unique_hero_id INTEGER PRIMARY KEY AUTOINCREMENT,
            account_id INTEGER NOT NULL,
            hero_id INTEGER NOT NULL,
            hero_index INTEGER NOT NULL,
            star INTEGER NOT NULL DEFAULT 2,
            level INTEGER NOT NULL DEFAULT 1,
            exp INTEGER NOT NULL DEFAULT 0,
            transcend INTEGER NOT NULL DEFAULT 0,
            awakened INTEGER NOT NULL DEFAULT 0,
            skill_level_1 INTEGER NOT NULL DEFAULT 1,
            skill_level_2 INTEGER NOT NULL DEFAULT 1,
            skill_level_3 INTEGER NOT NULL DEFAULT 1,
            skill_level_4 INTEGER NOT NULL DEFAULT 1,
            unique_weapon_id INTEGER NOT NULL DEFAULT 0,
            closeness INTEGER NOT NULL DEFAULT 0,
            is_bookmarked INTEGER NOT NULL DEFAULT 0,
            equip_item_slot_index_1 INTEGER NOT NULL DEFAULT 0,
            equip_item_slot_index_2 INTEGER NOT NULL DEFAULT 0,
            equip_item_slot_index_3 INTEGER NOT NULL DEFAULT 0,
            equip_item_slot_index_4 INTEGER NOT NULL DEFAULT 0,
            equip_item_slot_index_5 INTEGER NOT NULL DEFAULT 0,
            equip_item_slot_index_6 INTEGER NOT NULL DEFAULT 0,
            equip_item_slot_index_7 INTEGER NOT NULL DEFAULT 0,
            equip_item_slot_index_8 INTEGER NOT NULL DEFAULT 0,
            equip_item_slot_index_9 INTEGER NOT NULL DEFAULT 0,
            equip_item_slot_index_10 INTEGER NOT NULL DEFAULT 0,
            FOREIGN KEY (account_id) REFERENCES accounts(account_id),
            UNIQUE(account_id, hero_id)
        );
CREATE TABLE equip_items (
            slot_index INTEGER PRIMARY KEY AUTOINCREMENT,
            account_id INTEGER NOT NULL,
            item_index INTEGER NOT NULL,
            star INTEGER NOT NULL DEFAULT 0,
            level INTEGER NOT NULL DEFAULT 0,
            exp INTEGER NOT NULL DEFAULT 0,
            option_index_1 INTEGER NOT NULL DEFAULT 0,
            option_step_1 INTEGER NOT NULL DEFAULT 0,
            option_index_2 INTEGER NOT NULL DEFAULT 0,
            option_step_2 INTEGER NOT NULL DEFAULT 0,
            option_index_3 INTEGER NOT NULL DEFAULT 0,
            option_step_3 INTEGER NOT NULL DEFAULT 0,
            option_index_4 INTEGER NOT NULL DEFAULT 0,
            option_step_4 INTEGER NOT NULL DEFAULT 0,
            rune_slot_count INTEGER NOT NULL DEFAULT 0,
            rune_item_index_1 INTEGER NOT NULL DEFAULT 0,
            rune_item_index_2 INTEGER NOT NULL DEFAULT 0,
            rune_item_index_3 INTEGER NOT NULL DEFAULT 0,
            created_time TEXT NOT NULL DEFAULT (datetime('now')),
            upgrade_star_fail_bonus INTEGER NOT NULL DEFAULT 0,
            locked INTEGER NOT NULL DEFAULT 0,
            inventory_type INTEGER NOT NULL DEFAULT 0,
            identified INTEGER NOT NULL DEFAULT 1, option_renew_count_1 INTEGER NOT NULL DEFAULT 0, is_renewed_option_1 INTEGER NOT NULL DEFAULT 0, option_renew_count_2 INTEGER NOT NULL DEFAULT 0, is_renewed_option_2 INTEGER NOT NULL DEFAULT 0, option_renew_count_3 INTEGER NOT NULL DEFAULT 0, is_renewed_option_3 INTEGER NOT NULL DEFAULT 0, option_renew_count_4 INTEGER NOT NULL DEFAULT 0, is_renewed_option_4 INTEGER NOT NULL DEFAULT 0, apply_rune_page INTEGER NOT NULL DEFAULT 0, enchant_option_index_1 INTEGER NOT NULL DEFAULT 0, enchant_option_index_2 INTEGER NOT NULL DEFAULT 0, enchant_option_index_3 INTEGER NOT NULL DEFAULT 0, enchant_option_step_1 INTEGER NOT NULL DEFAULT 0, enchant_option_step_2 INTEGER NOT NULL DEFAULT 0, enchant_option_step_3 INTEGER NOT NULL DEFAULT 0, extra_option_index_1 INTEGER NOT NULL DEFAULT 0, extra_option_index_2 INTEGER NOT NULL DEFAULT 0, extra_option_renew_count_1 INTEGER NOT NULL DEFAULT 0, extra_option_renew_count_2 INTEGER NOT NULL DEFAULT 0, extra_option_step_1 INTEGER NOT NULL DEFAULT 0, extra_option_step_2 INTEGER NOT NULL DEFAULT 0, is_renewed_extra_option_1 INTEGER NOT NULL DEFAULT 0, is_renewed_extra_option_2 INTEGER NOT NULL DEFAULT 0, is_renewed_option_5 INTEGER NOT NULL DEFAULT 0, option_index_5 INTEGER NOT NULL DEFAULT 0, option_renew_count_5 INTEGER NOT NULL DEFAULT 0, option_step_5 INTEGER NOT NULL DEFAULT 0, renew_enchant_option_slot_index INTEGER NOT NULL DEFAULT 0, punishment_rune_option TEXT,
            FOREIGN KEY (account_id) REFERENCES accounts(account_id)
        );
CREATE TABLE items (
            item_id INTEGER PRIMARY KEY AUTOINCREMENT,
            account_id INTEGER NOT NULL,
            item_index INTEGER NOT NULL,
            count INTEGER NOT NULL DEFAULT 1, locked INTEGER NOT NULL DEFAULT 0, created_time TEXT,
            FOREIGN KEY (account_id) REFERENCES accounts(account_id),
            UNIQUE(account_id, item_index)
        );
CREATE TABLE guilds (
            guild_id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT UNIQUE NOT NULL,
            notice TEXT,
            level INTEGER NOT NULL DEFAULT 1,
            exp INTEGER NOT NULL DEFAULT 0,
            master_account_id INTEGER NOT NULL,
            member_count INTEGER NOT NULL DEFAULT 1,
            max_members INTEGER NOT NULL DEFAULT 30,
            created_at TEXT NOT NULL DEFAULT (datetime('now')),
            FOREIGN KEY (master_account_id) REFERENCES accounts(account_id)
        );
CREATE TABLE guild_members (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            account_id INTEGER NOT NULL UNIQUE,
            guild_id INTEGER NOT NULL,
            role INTEGER NOT NULL DEFAULT 0,
            contribution INTEGER NOT NULL DEFAULT 0,
            joined_at TEXT NOT NULL DEFAULT (datetime('now')),
            FOREIGN KEY (account_id) REFERENCES accounts(account_id),
            FOREIGN KEY (guild_id) REFERENCES guilds(guild_id)
        );
CREATE TABLE mails (
            mail_id INTEGER PRIMARY KEY AUTOINCREMENT,
            account_id INTEGER NOT NULL,
            sender TEXT NOT NULL DEFAULT 'System',
            title TEXT NOT NULL,
            content TEXT,
            reward_gold INTEGER DEFAULT 0,
            reward_gem INTEGER DEFAULT 0,
            reward_items TEXT,
            is_read INTEGER NOT NULL DEFAULT 0,
            is_received INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL DEFAULT (datetime('now')),
            expires_at TEXT, read_time TEXT, received_time TEXT, opens_at TEXT, reward_stamina INTEGER NOT NULL DEFAULT 0, reward_equipment TEXT, global_id INTEGER, receipt TEXT, reward_currencies TEXT,
            FOREIGN KEY (account_id) REFERENCES accounts(account_id)
        );
CREATE TABLE friends (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            account_id INTEGER NOT NULL,
            friend_account_id INTEGER NOT NULL,
            status TEXT NOT NULL DEFAULT 'pending',
            created_at TEXT NOT NULL DEFAULT (datetime('now')),
            FOREIGN KEY (account_id) REFERENCES accounts(account_id),
            FOREIGN KEY (friend_account_id) REFERENCES accounts(account_id),
            UNIQUE(account_id, friend_account_id)
        );
CREATE TABLE campaign_progress (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            account_id INTEGER NOT NULL,
            chapter_id INTEGER NOT NULL,
            dungeon_id INTEGER NOT NULL,
            clear_count INTEGER NOT NULL DEFAULT 0,
            best_star INTEGER NOT NULL DEFAULT 0,
            is_unlocked INTEGER NOT NULL DEFAULT 0,
            completed_time TEXT,
            FOREIGN KEY (account_id) REFERENCES accounts(account_id),
            UNIQUE(account_id, chapter_id, dungeon_id)
        );
CREATE TABLE tutorial_progress (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            account_id INTEGER NOT NULL,
            tutorial_index INTEGER NOT NULL,
            is_completed INTEGER NOT NULL DEFAULT 0,
            completed_time TEXT, completion_response TEXT,
            FOREIGN KEY (account_id) REFERENCES accounts(account_id),
            UNIQUE(account_id, tutorial_index)
        );
CREATE TABLE attendance (
            account_id INTEGER PRIMARY KEY,
            current_day INTEGER NOT NULL DEFAULT 0,
            total_days INTEGER NOT NULL DEFAULT 0,
            last_attendance TEXT NOT NULL DEFAULT '',
            FOREIGN KEY (account_id) REFERENCES accounts(account_id)
        );
CREATE TABLE achievements (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            account_id INTEGER NOT NULL,
            achievement_id INTEGER NOT NULL,
            category INTEGER NOT NULL DEFAULT 0,
            current_value INTEGER NOT NULL DEFAULT 0,
            target_value INTEGER NOT NULL DEFAULT 0,
            is_completed INTEGER NOT NULL DEFAULT 0,
            is_rewarded INTEGER NOT NULL DEFAULT 0,
            FOREIGN KEY (account_id) REFERENCES accounts(account_id),
            UNIQUE(account_id, achievement_id)
        );
CREATE TABLE sessions (
            session_id TEXT PRIMARY KEY,
            account_id INTEGER NOT NULL,
            aes_key TEXT NOT NULL,
            created_at TEXT NOT NULL DEFAULT (datetime('now')),
            last_activity TEXT NOT NULL DEFAULT (datetime('now')),
            FOREIGN KEY (account_id) REFERENCES accounts(account_id)
        );
CREATE TABLE hero_friendly_state (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            account_id INTEGER NOT NULL,
            hero_index INTEGER NOT NULL,
            friendly_point INTEGER NOT NULL DEFAULT 0,
            step INTEGER NOT NULL DEFAULT 0,
            action_reset_count INTEGER NOT NULL DEFAULT 0,
            last_greeting_time TEXT,
            last_conversation_time TEXT,
            last_gift_time TEXT,
            is_lock INTEGER NOT NULL DEFAULT 0,
            selected_time TEXT,
            visit_period INTEGER NOT NULL DEFAULT 0,
            FOREIGN KEY (account_id) REFERENCES accounts(account_id),
            UNIQUE(account_id, hero_index)
        );
CREATE TABLE hero_friendly_info (
            account_id INTEGER PRIMARY KEY,
            hero_index INTEGER NOT NULL DEFAULT 0,
            selected_hero_index INTEGER NOT NULL DEFAULT 0,
            friendly_point INTEGER NOT NULL DEFAULT 0,
            last_greeting_time TEXT,
            last_conversation_time TEXT,
            last_gift_time TEXT,
            selected_time TEXT,
            selected_hero_indices TEXT,
            last_roulette_time TEXT,
            FOREIGN KEY (account_id) REFERENCES accounts(account_id)
        );
CREATE TABLE hero_inn_roulette_spins (
            account_id INTEGER NOT NULL,
            spin_date TEXT NOT NULL,
            spin_count INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY (account_id, spin_date),
            FOREIGN KEY (account_id) REFERENCES accounts(account_id)
        );
CREATE TABLE inventory (
            account_id INTEGER NOT NULL,
            item_code INTEGER NOT NULL,
            count INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY (account_id, item_code),
            FOREIGN KEY (account_id) REFERENCES accounts(account_id)
        );
CREATE TABLE shop_purchases (
            account_id INTEGER NOT NULL,
            shop_index INTEGER NOT NULL,
            item_index INTEGER NOT NULL,
            purchase_count INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY (account_id, shop_index, item_index),
            FOREIGN KEY (account_id) REFERENCES accounts(account_id)
        );
CREATE TABLE tutorial_settings (account_id INTEGER PRIMARY KEY, is_skipped INTEGER NOT NULL DEFAULT 0, FOREIGN KEY (account_id) REFERENCES accounts(account_id));
CREATE TABLE friend_points (account_id INTEGER NOT NULL, friend_id INTEGER NOT NULL, last_send_time TEXT, last_recv_time TEXT, PRIMARY KEY(account_id, friend_id));
CREATE TABLE friend_daily (account_id INTEGER PRIMARY KEY, day TEXT NOT NULL, points INTEGER NOT NULL DEFAULT 0, removed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE global_mails (global_id INTEGER PRIMARY KEY AUTOINCREMENT, sender TEXT NOT NULL DEFAULT 'System', title TEXT NOT NULL, content TEXT NOT NULL DEFAULT '', reward_gold INTEGER NOT NULL DEFAULT 0, reward_gem INTEGER NOT NULL DEFAULT 0, reward_items TEXT, reward_stamina INTEGER NOT NULL DEFAULT 0, reward_equipment TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), expires_at TEXT, opens_at TEXT);
CREATE TABLE global_mail_deliveries (account_id INTEGER NOT NULL, global_id INTEGER NOT NULL, mail_id INTEGER NOT NULL, PRIMARY KEY(account_id, global_id));
CREATE TABLE chat_messages (message_id INTEGER PRIMARY KEY AUTOINCREMENT, sender_id INTEGER NOT NULL, group_type TEXT NOT NULL, channel INTEGER NOT NULL DEFAULT 1, guild_id INTEGER NOT NULL DEFAULT 0, receiver_id INTEGER NOT NULL DEFAULT 0, protocol TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX chat_channel_history ON chat_messages(group_type, channel, message_id);
CREATE INDEX chat_whisper_history ON chat_messages(receiver_id, sender_id, message_id);
CREATE INDEX mail_inbox ON mails(account_id, is_received, mail_id);
CREATE TABLE mail_notifications(mail_id INTEGER PRIMARY KEY,account_id INTEGER NOT NULL,is_global INTEGER NOT NULL);
CREATE TRIGGER mail_arrival_notification AFTER INSERT ON mails BEGIN INSERT INTO mail_notifications(mail_id,account_id,is_global) VALUES(NEW.mail_id,NEW.account_id,NEW.global_id IS NOT NULL); END;
CREATE TABLE inventory_settings(account_id INTEGER PRIMARY KEY, inventory_extend INTEGER NOT NULL DEFAULT 0, chest_extend INTEGER NOT NULL DEFAULT 0);
CREATE TABLE inventory_ticket_redemptions(account_id INTEGER NOT NULL,token TEXT NOT NULL,request TEXT NOT NULL,response TEXT NOT NULL,PRIMARY KEY(account_id,token));
CREATE TABLE craft_slots(account_id INTEGER NOT NULL, slot_index INTEGER NOT NULL, craft_index INTEGER NOT NULL DEFAULT 0, item_index INTEGER NOT NULL DEFAULT 0, item_count INTEGER NOT NULL DEFAULT 0, complete_time INTEGER NOT NULL DEFAULT 0, paid_gold INTEGER NOT NULL DEFAULT 0, materials TEXT NOT NULL DEFAULT '[]', PRIMARY KEY(account_id,slot_index));
CREATE TABLE item_boosters(account_id INTEGER NOT NULL, item_index INTEGER NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL, PRIMARY KEY(account_id,item_index));
CREATE TABLE hero_presets(account_id INTEGER NOT NULL,storage_key TEXT NOT NULL,name TEXT NOT NULL DEFAULT '',data TEXT NOT NULL DEFAULT '[]',PRIMARY KEY(account_id,storage_key));
CREATE TABLE hero_details(account_id INTEGER NOT NULL,hero_index INTEGER NOT NULL,data TEXT NOT NULL DEFAULT '{}',PRIMARY KEY(account_id,hero_index));
CREATE TABLE costumes(account_id INTEGER NOT NULL,costume_index INTEGER NOT NULL,created_time TEXT NOT NULL DEFAULT (datetime('now')),PRIMARY KEY(account_id,costume_index));
CREATE TABLE costume_presets(account_id INTEGER NOT NULL,hero_index INTEGER NOT NULL,slot_index INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(account_id,hero_index,slot_index));
CREATE TABLE lobby_appearance(account_id INTEGER PRIMARY KEY,avatar_hero_index INTEGER NOT NULL,costume_index INTEGER NOT NULL,hair_costume_index INTEGER NOT NULL,weapon_costume_index INTEGER NOT NULL,hide_unique_weapon INTEGER NOT NULL,snapshot TEXT);
CREATE TABLE shop_stock(account_id INTEGER NOT NULL,shop_index INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,restock_time INTEGER NOT NULL DEFAULT 0,restock_count INTEGER NOT NULL DEFAULT 0,stock TEXT NOT NULL DEFAULT '[]',PRIMARY KEY(account_id,shop_index));
CREATE TABLE shop_purchase_ledger(account_id INTEGER NOT NULL,shop_index INTEGER NOT NULL,item_index INTEGER NOT NULL,period TEXT NOT NULL,purchased INTEGER NOT NULL DEFAULT 0,purchased_time INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(account_id,shop_index,item_index,period));
CREATE TABLE mission_category_seen(account_id INTEGER NOT NULL,main_category INTEGER NOT NULL,sub_category INTEGER NOT NULL,PRIMARY KEY(account_id,main_category,sub_category));
CREATE TABLE progression_claims(account_id INTEGER NOT NULL,family TEXT NOT NULL,idx INTEGER NOT NULL,step INTEGER NOT NULL DEFAULT 1,period TEXT NOT NULL DEFAULT 'all',claimed_time TEXT NOT NULL DEFAULT (datetime('now')),PRIMARY KEY(account_id,family,idx,step,period));
CREATE TABLE progression_metrics(account_id INTEGER NOT NULL,day TEXT NOT NULL,kind TEXT NOT NULL,arg INTEGER NOT NULL DEFAULT 0,arg2 INTEGER NOT NULL DEFAULT 0,value INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(account_id,day,kind,arg,arg2));
CREATE TABLE progression_login(account_id INTEGER PRIMARY KEY,days INTEGER NOT NULL DEFAULT 0,last_day TEXT NOT NULL DEFAULT '');
CREATE TABLE attendance_calendar_state(account_id INTEGER NOT NULL,idx INTEGER NOT NULL,claims INTEGER NOT NULL DEFAULT 0,last_day TEXT NOT NULL DEFAULT '',completed_time TEXT,PRIMARY KEY(account_id,idx));
CREATE TABLE progression_entitlements(account_id INTEGER NOT NULL,product_index INTEGER NOT NULL,created_time TEXT NOT NULL DEFAULT (datetime('now')),PRIMARY KEY(account_id,product_index));
CREATE TABLE progression_world_events(account_id INTEGER NOT NULL,chapter INTEGER NOT NULL,dungeon INTEGER NOT NULL,event INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(account_id,chapter,dungeon,event));
CREATE TABLE progression_main_quest(account_id INTEGER PRIMARY KEY,step INTEGER NOT NULL DEFAULT 0,progress INTEGER NOT NULL DEFAULT 0);
CREATE TRIGGER progression_spend_gold AFTER UPDATE ON user_info WHEN NEW.gold<OLD.gold BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'ConsumeGold',0,0,OLD.gold-NEW.gold) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_gain_gold AFTER UPDATE ON user_info WHEN NEW.gold>OLD.gold BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'GetGold',0,0,NEW.gold-OLD.gold) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_spend_gem AFTER UPDATE ON user_info WHEN NEW.gem+NEW.pay_gem<OLD.gem+OLD.pay_gem BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'ConsumeGem',0,0,OLD.gem+OLD.pay_gem-NEW.gem-NEW.pay_gem) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_spend_stamina AFTER UPDATE ON user_info WHEN NEW.stamina<OLD.stamina BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'ConsumeStamina',0,0,OLD.stamina-NEW.stamina) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_stamina_uses AFTER UPDATE ON user_info WHEN NEW.stamina<OLD.stamina BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'StaminaUses',0,0,1) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_friend_send AFTER UPDATE ON friend_points WHEN NEW.last_send_time IS NOT NULL AND (OLD.last_send_time IS NULL OR NEW.last_send_time!=OLD.last_send_time) BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'SendFriendshipPoint',0,0,1) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_friend_request AFTER INSERT ON friends WHEN NEW.status='pending' BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'FriendRequest',0,0,1) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_clear_insert AFTER INSERT ON campaign_progress WHEN NEW.clear_count>0 BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'ClearDungeon',NEW.chapter_id,NEW.dungeon_id,NEW.clear_count) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_clear_update AFTER UPDATE ON campaign_progress WHEN NEW.clear_count>OLD.clear_count BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'ClearDungeon',NEW.chapter_id,NEW.dungeon_id,NEW.clear_count-OLD.clear_count) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_roulette_first AFTER INSERT ON hero_inn_roulette_spins WHEN NEW.spin_count>0 BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'RotateRulletDaily',0,0,NEW.spin_count) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_roulette_more AFTER UPDATE ON hero_inn_roulette_spins WHEN NEW.spin_count>OLD.spin_count BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'RotateRulletDaily',0,0,NEW.spin_count-OLD.spin_count) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_item_new AFTER INSERT ON items WHEN NEW.count>0 BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'AddItem',NEW.item_index,0,NEW.count) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_item_gain AFTER UPDATE ON items WHEN NEW.count>OLD.count BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'AddItem',NEW.item_index,0,NEW.count-OLD.count) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_equip_gain AFTER INSERT ON equip_items WHEN 1 BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'AddEquip',NEW.item_index,0,1) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_shop_new AFTER INSERT ON shop_purchase_ledger WHEN NEW.purchased>0 BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'BuyShopItem',NEW.shop_index,NEW.item_index,NEW.purchased) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_shop_more AFTER UPDATE ON shop_purchase_ledger WHEN NEW.purchased>OLD.purchased BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'BuyShopItem',NEW.shop_index,NEW.item_index,NEW.purchased-OLD.purchased) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_shop_restock AFTER UPDATE ON shop_stock WHEN NEW.restock_count>OLD.restock_count BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'ResetShop',NEW.shop_index,0,1) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_hero_friendly AFTER UPDATE ON hero_friendly_state WHEN NEW.friendly_point>OLD.friendly_point BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'DoHeroFriendly',NEW.hero_index,0,1) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_inn_greet AFTER UPDATE ON hero_friendly_info WHEN NEW.last_greeting_time IS NOT NULL AND NEW.last_greeting_time IS NOT OLD.last_greeting_time BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'DoHeroFriendly',NEW.hero_index,0,1) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_inn_conversation AFTER UPDATE ON hero_friendly_info WHEN NEW.last_conversation_time IS NOT NULL AND NEW.last_conversation_time IS NOT OLD.last_conversation_time BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'DoHeroFriendly',NEW.hero_index,0,1) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_inn_gift AFTER UPDATE ON hero_friendly_info WHEN NEW.last_gift_time IS NOT NULL AND NEW.last_gift_time IS NOT OLD.last_gift_time BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'DoHeroFriendly',NEW.hero_index,0,1) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER progression_mail_received AFTER UPDATE ON mails WHEN NEW.is_received=1 AND OLD.is_received=0 BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account_id,date('now'),'ReceiveMail',0,0,1) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+excluded.value; END;
CREATE TABLE equipment_pending(account_id INTEGER NOT NULL,slot_index INTEGER NOT NULL,kind TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(account_id,slot_index,kind),FOREIGN KEY(slot_index) REFERENCES equip_items(slot_index) ON DELETE CASCADE);
CREATE TABLE extension_state(account_id INTEGER NOT NULL,kind TEXT NOT NULL,idx INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(account_id,kind,idx));
CREATE TABLE challenge_results(season INTEGER NOT NULL,challenge INTEGER NOT NULL,account INTEGER NOT NULL,score INTEGER NOT NULL,battle_time INTEGER NOT NULL,current_score INTEGER NOT NULL,current_time INTEGER NOT NULL,PRIMARY KEY(season,challenge,account));
CREATE TABLE challenge_teams(season INTEGER NOT NULL,challenge INTEGER NOT NULL,team TEXT NOT NULL,score INTEGER NOT NULL,battle_time INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(season,challenge,team));
CREATE TABLE battle_state(account INTEGER NOT NULL,kind TEXT NOT NULL,idx INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(account,kind,idx));
CREATE TABLE battle_runs(account INTEGER PRIMARY KEY,run_id TEXT NOT NULL,started INTEGER NOT NULL,completed INTEGER NOT NULL DEFAULT 0,entry TEXT NOT NULL,begin_response TEXT NOT NULL);
CREATE TABLE battle_rooms(id INTEGER PRIMARY KEY AUTOINCREMENT,family TEXT NOT NULL,master INTEGER NOT NULL,data TEXT NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE battle_room_members(account INTEGER PRIMARY KEY,room INTEGER NOT NULL,joined INTEGER NOT NULL,updated INTEGER NOT NULL,FOREIGN KEY(room) REFERENCES battle_rooms(id) ON DELETE CASCADE);
CREATE TABLE battle_scores(family TEXT NOT NULL,boss INTEGER NOT NULL,season INTEGER NOT NULL,account INTEGER NOT NULL,day TEXT NOT NULL,score INTEGER NOT NULL,battle_time INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(family,boss,season,account,day));
CREATE TABLE battle_reward_claims(account INTEGER NOT NULL,kind TEXT NOT NULL,idx INTEGER NOT NULL,period TEXT NOT NULL,PRIMARY KEY(account,kind,idx,period));
CREATE TABLE battle_currencies(account INTEGER NOT NULL,kind TEXT NOT NULL,value INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(account,kind));
CREATE TABLE eclipse_run_ids(id INTEGER PRIMARY KEY AUTOINCREMENT,account INTEGER NOT NULL);
CREATE TABLE battle_entry_holds(account INTEGER NOT NULL,owner TEXT NOT NULL,family TEXT NOT NULL,kind INTEGER NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),expires INTEGER NOT NULL,PRIMARY KEY(account,owner,family,kind));
CREATE TRIGGER progress_world_boss_complete_insert AFTER INSERT ON battle_scores WHEN NEW.family='world_boss' AND NEW.score>0 BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account,NEW.day,'CompleteWorldBoss',NEW.boss,0,1) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+1; END;
CREATE TRIGGER progress_world_boss_complete_update AFTER UPDATE ON battle_scores WHEN NEW.family='world_boss' AND NEW.score>OLD.score BEGIN INSERT INTO progression_metrics(account_id,day,kind,arg,arg2,value) VALUES(NEW.account,NEW.day,'CompleteWorldBoss',NEW.boss,0,1) ON CONFLICT(account_id,day,kind,arg,arg2) DO UPDATE SET value=value+1; END;
CREATE INDEX battle_state_dispatch_pending ON battle_state(account,idx) WHERE kind='dispatch' AND json_extract(data,'$.SimulationVersion') IN (1,2) AND json_extract(data,'$.State') NOT IN ('Complete','Cancel') AND COALESCE(json_array_length(json_extract(data,'$.SimulationResults')),0)<json_extract(data,'$.RepeatCount');
CREATE TABLE world_boss_legacy_scores(boss INTEGER NOT NULL,season INTEGER NOT NULL,account INTEGER NOT NULL,day TEXT NOT NULL,score INTEGER NOT NULL,battle_time INTEGER NOT NULL,PRIMARY KEY(boss,season,account,day));
CREATE TABLE service_replays(id INTEGER PRIMARY KEY AUTOINCREMENT,owner INTEGER NOT NULL,kind INTEGER NOT NULL,info TEXT NOT NULL,data TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE service_replay_accounts(replay INTEGER NOT NULL,account INTEGER NOT NULL,PRIMARY KEY(replay,account),FOREIGN KEY(replay) REFERENCES service_replays(id) ON DELETE CASCADE);
CREATE INDEX service_replay_account ON service_replay_accounts(account,replay);
CREATE TABLE service_decks(account INTEGER NOT NULL,chapter INTEGER NOT NULL,dungeon INTEGER NOT NULL,difficulty INTEGER NOT NULL,kind INTEGER NOT NULL,metric INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(account,chapter,dungeon,difficulty,kind));
CREATE TABLE service_results(run TEXT PRIMARY KEY,account INTEGER NOT NULL,request TEXT NOT NULL,response TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE service_servers(name TEXT PRIMARY KEY,data TEXT NOT NULL,seen INTEGER NOT NULL);
CREATE TABLE service_reports(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL,data TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX service_deck_rank ON service_decks(chapter,dungeon,difficulty,kind,metric,account);
CREATE TABLE community_state(owner INTEGER NOT NULL,kind TEXT NOT NULL,idx INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(owner,kind,idx));
CREATE TABLE community_claims(account INTEGER NOT NULL,kind TEXT NOT NULL,target INTEGER NOT NULL,period TEXT NOT NULL,PRIMARY KEY(account,kind,target,period));
CREATE TABLE guild_requests(account INTEGER NOT NULL,guild_id INTEGER NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(account,guild_id),FOREIGN KEY(guild_id) REFERENCES guilds(guild_id) ON DELETE CASCADE);
CREATE TABLE arena_runs(id INTEGER PRIMARY KEY AUTOINCREMENT,account INTEGER NOT NULL,kind INTEGER NOT NULL,started INTEGER NOT NULL,status TEXT NOT NULL,data TEXT NOT NULL, mission_summary TEXT, season INTEGER, nonduel INTEGER, squad INTEGER, last_poll INTEGER);
CREATE UNIQUE INDEX arena_active_account ON arena_runs(account) WHERE status IN ('waiting','battle');
CREATE INDEX arena_completed_squad ON arena_runs(account,kind,json_extract(data,'$.Season'),id DESC) WHERE status='complete';
CREATE INDEX arena_online_match_status ON arena_runs(json_extract(data,'$.OnlineMatchUid'),status) WHERE json_extract(data,'$.OnlineMatchUid') IS NOT NULL;
CREATE TABLE arena_snapshots(run INTEGER PRIMARY KEY,data TEXT NOT NULL);
CREATE TRIGGER arena_snapshots_cleanup AFTER DELETE ON arena_runs BEGIN DELETE FROM arena_snapshots WHERE run=OLD.id; END;
CREATE TABLE arena_scores(account INTEGER NOT NULL,kind INTEGER NOT NULL,season INTEGER NOT NULL,score INTEGER NOT NULL,wins INTEGER NOT NULL DEFAULT 0,losses INTEGER NOT NULL DEFAULT 0,data TEXT NOT NULL DEFAULT '{}',PRIMARY KEY(account,kind,season));
CREATE TABLE guild_battle_scores(guild_id INTEGER NOT NULL,account INTEGER NOT NULL,kind TEXT NOT NULL,season INTEGER NOT NULL,stage INTEGER NOT NULL,score INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(guild_id,account,kind,season,stage));
CREATE INDEX guild_battle_scores_account_kind ON guild_battle_scores(account,kind);
CREATE TABLE guild_arena_decks(guild_id INTEGER NOT NULL,account INTEGER NOT NULL,season INTEGER NOT NULL,deck INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(account,season,deck));
CREATE TABLE friendly_duels(group_id INTEGER PRIMARY KEY,requester INTEGER NOT NULL,opponent INTEGER NOT NULL,status TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE guild_arena_records(id INTEGER PRIMARY KEY AUTOINCREMENT,guild_id INTEGER NOT NULL,enemy_guild INTEGER NOT NULL,account INTEGER NOT NULL,enemy INTEGER NOT NULL,season INTEGER NOT NULL,win INTEGER NOT NULL,data TEXT NOT NULL);
CREATE TRIGGER arena_mission_summary_insert AFTER INSERT ON arena_runs WHEN NEW.status='complete' BEGIN UPDATE arena_runs SET mission_summary=json_object('DuelType',COALESCE(json_extract(NEW.data,'$.DuelType'),0),'CompletedAt',json_extract(NEW.data,'$.CompletedAt'),'End',json_object('MatchResult',json_extract(NEW.data,'$.End.MatchResult'),'BattleInfo',json_object('SuccessiveWin',json_extract(NEW.data,'$.End.BattleInfo.SuccessiveWin')),'BattleBanPickInfo',json_object('SuccessiveWin',json_extract(NEW.data,'$.End.BattleBanPickInfo.SuccessiveWin')))) WHERE id=NEW.id; END;
CREATE TRIGGER arena_mission_summary_update AFTER UPDATE OF status,data ON arena_runs WHEN NEW.status='complete' BEGIN UPDATE arena_runs SET mission_summary=json_object('DuelType',COALESCE(json_extract(NEW.data,'$.DuelType'),0),'CompletedAt',json_extract(NEW.data,'$.CompletedAt'),'End',json_object('MatchResult',json_extract(NEW.data,'$.End.MatchResult'),'BattleInfo',json_object('SuccessiveWin',json_extract(NEW.data,'$.End.BattleInfo.SuccessiveWin')),'BattleBanPickInfo',json_object('SuccessiveWin',json_extract(NEW.data,'$.End.BattleBanPickInfo.SuccessiveWin')))) WHERE id=NEW.id; END;
CREATE INDEX arena_mission_history ON arena_runs(account,status,id,kind,started,mission_summary) WHERE status='complete';
CREATE TABLE arena_history_archive(account INTEGER NOT NULL,kind INTEGER NOT NULL,day TEXT NOT NULL,matches INTEGER NOT NULL,wins INTEGER NOT NULL,best_streak INTEGER NOT NULL,best_tier INTEGER NOT NULL,PRIMARY KEY(account,kind,day)) WITHOUT ROWID;
CREATE TRIGGER arena_retention_keys_insert AFTER INSERT ON arena_runs BEGIN UPDATE arena_runs SET season=json_extract(NEW.data,'$.Season'),nonduel=(json_extract(NEW.data,'$.DuelType') IS NOT 1),squad=(json_extract(NEW.data,'$.DuelType') IS NOT 1 AND COALESCE(json_array_length(NEW.data,'$.Heroes') BETWEEN 1 AND 4,0)) WHERE id=NEW.id; END;
CREATE TRIGGER arena_retention_keys_update AFTER UPDATE OF data ON arena_runs BEGIN UPDATE arena_runs SET season=json_extract(NEW.data,'$.Season'),nonduel=(json_extract(NEW.data,'$.DuelType') IS NOT 1),squad=(json_extract(NEW.data,'$.DuelType') IS NOT 1 AND COALESCE(json_array_length(NEW.data,'$.Heroes') BETWEEN 1 AND 4,0)) WHERE id=NEW.id; END;
CREATE INDEX arena_retention ON arena_runs(account,kind,id,status,season,nonduel,squad);
CREATE TRIGGER arena_retention_finish AFTER UPDATE OF status ON arena_runs WHEN OLD.status IN ('waiting','battle') AND NEW.status NOT IN ('waiting','battle') BEGIN INSERT INTO arena_history_archive(account,kind,day,matches,wins,best_streak,best_tier) SELECT account,kind,date(MAX(COALESCE(json_extract(mission_summary,'$.CompletedAt'),0),started),'unixepoch') AS day,COUNT(*),SUM(COALESCE(json_extract(mission_summary,'$.End.MatchResult.Win'),0)=1),MAX(COALESCE(json_extract(mission_summary,CASE kind WHEN 1 THEN '$.End.BattleBanPickInfo.SuccessiveWin' ELSE '$.End.BattleInfo.SuccessiveWin' END),0)),MAX(COALESCE(json_extract(mission_summary,'$.End.MatchResult.NewTierIndex'),0)) FROM arena_runs WHERE id IN (SELECT id FROM (SELECT id,status,squad,nonduel,ROW_NUMBER() OVER (PARTITION BY kind ORDER BY id DESC) AS recent,ROW_NUMBER() OVER (PARTITION BY kind,season,status='complete' ORDER BY id DESC) AS season_last,ROW_NUMBER() OVER (PARTITION BY kind,season,status='complete' AND squad ORDER BY id DESC) AS squad_last,ROW_NUMBER() OVER (PARTITION BY kind,nonduel ORDER BY id DESC) AS defense_last FROM arena_runs WHERE account=NEW.account AND status NOT IN ('waiting','battle')) WHERE recent>20 AND NOT (status='complete' AND season_last=1) AND NOT (status='complete' AND squad AND squad_last=1) AND NOT (nonduel AND defense_last=1)) AND status='complete' 
        AND COALESCE(json_extract(mission_summary,'$.DuelType'),0)!=1 AND json_type(mission_summary,'$.End.MatchResult')='object' AND COALESCE(json_extract(mission_summary,'$.End.MatchResult.Canceled'),0)!=1 
        GROUP BY account,kind,day ON CONFLICT(account,kind,day) DO UPDATE SET matches=matches+excluded.matches,wins=wins+excluded.wins,best_streak=MAX(best_streak,excluded.best_streak),best_tier=MAX(best_tier,excluded.best_tier); DELETE FROM arena_runs WHERE id IN (SELECT id FROM (SELECT id,status,squad,nonduel,ROW_NUMBER() OVER (PARTITION BY kind ORDER BY id DESC) AS recent,ROW_NUMBER() OVER (PARTITION BY kind,season,status='complete' ORDER BY id DESC) AS season_last,ROW_NUMBER() OVER (PARTITION BY kind,season,status='complete' AND squad ORDER BY id DESC) AS squad_last,ROW_NUMBER() OVER (PARTITION BY kind,nonduel ORDER BY id DESC) AS defense_last FROM arena_runs WHERE account=NEW.account AND status NOT IN ('waiting','battle')) WHERE recent>20 AND NOT (status='complete' AND season_last=1) AND NOT (status='complete' AND squad AND squad_last=1) AND NOT (nonduel AND defense_last=1)); END;
CREATE TRIGGER arena_retention_insert AFTER INSERT ON arena_runs WHEN NEW.status NOT IN ('waiting','battle') BEGIN INSERT INTO arena_history_archive(account,kind,day,matches,wins,best_streak,best_tier) SELECT account,kind,date(MAX(COALESCE(json_extract(mission_summary,'$.CompletedAt'),0),started),'unixepoch') AS day,COUNT(*),SUM(COALESCE(json_extract(mission_summary,'$.End.MatchResult.Win'),0)=1),MAX(COALESCE(json_extract(mission_summary,CASE kind WHEN 1 THEN '$.End.BattleBanPickInfo.SuccessiveWin' ELSE '$.End.BattleInfo.SuccessiveWin' END),0)),MAX(COALESCE(json_extract(mission_summary,'$.End.MatchResult.NewTierIndex'),0)) FROM arena_runs WHERE id IN (SELECT id FROM (SELECT id,status,squad,nonduel,ROW_NUMBER() OVER (PARTITION BY kind ORDER BY id DESC) AS recent,ROW_NUMBER() OVER (PARTITION BY kind,season,status='complete' ORDER BY id DESC) AS season_last,ROW_NUMBER() OVER (PARTITION BY kind,season,status='complete' AND squad ORDER BY id DESC) AS squad_last,ROW_NUMBER() OVER (PARTITION BY kind,nonduel ORDER BY id DESC) AS defense_last FROM arena_runs WHERE account=NEW.account AND status NOT IN ('waiting','battle')) WHERE recent>20 AND NOT (status='complete' AND season_last=1) AND NOT (status='complete' AND squad AND squad_last=1) AND NOT (nonduel AND defense_last=1)) AND status='complete' 
        AND COALESCE(json_extract(mission_summary,'$.DuelType'),0)!=1 AND json_type(mission_summary,'$.End.MatchResult')='object' AND COALESCE(json_extract(mission_summary,'$.End.MatchResult.Canceled'),0)!=1 
        GROUP BY account,kind,day ON CONFLICT(account,kind,day) DO UPDATE SET matches=matches+excluded.matches,wins=wins+excluded.wins,best_streak=MAX(best_streak,excluded.best_streak),best_tier=MAX(best_tier,excluded.best_tier); DELETE FROM arena_runs WHERE id IN (SELECT id FROM (SELECT id,status,squad,nonduel,ROW_NUMBER() OVER (PARTITION BY kind ORDER BY id DESC) AS recent,ROW_NUMBER() OVER (PARTITION BY kind,season,status='complete' ORDER BY id DESC) AS season_last,ROW_NUMBER() OVER (PARTITION BY kind,season,status='complete' AND squad ORDER BY id DESC) AS squad_last,ROW_NUMBER() OVER (PARTITION BY kind,nonduel ORDER BY id DESC) AS defense_last FROM arena_runs WHERE account=NEW.account AND status NOT IN ('waiting','battle')) WHERE recent>20 AND NOT (status='complete' AND season_last=1) AND NOT (status='complete' AND squad AND squad_last=1) AND NOT (nonduel AND defense_last=1)); END;
CREATE INDEX arena_waiting_queue ON arena_runs(kind,started) WHERE status='waiting';
CREATE TABLE client_storage_reports(account_id INTEGER NOT NULL,installation TEXT NOT NULL,schema_version INTEGER NOT NULL,source_present INTEGER NOT NULL,files_copied INTEGER NOT NULL,preferences_copied INTEGER NOT NULL,first_seen TEXT NOT NULL DEFAULT (datetime('now')),last_seen TEXT NOT NULL DEFAULT (datetime('now')),PRIMARY KEY(account_id,installation),FOREIGN KEY(account_id) REFERENCES accounts(account_id) ON DELETE CASCADE);
CREATE TABLE play_record_values(account_id INTEGER NOT NULL,kind TEXT NOT NULL,idx INTEGER NOT NULL DEFAULT 0,value INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(account_id,kind,idx));
CREATE TRIGGER play_record_equip_count AFTER INSERT ON equip_items WHEN 1 BEGIN INSERT INTO play_record_values(account_id,kind,idx,value) VALUES(NEW.account_id,'equip_count',NEW.item_index,1) ON CONFLICT(account_id,kind,idx) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER play_record_equip_star_new AFTER INSERT ON equip_items WHEN 1 BEGIN INSERT INTO play_record_values(account_id,kind,idx,value) VALUES(NEW.account_id,'equip_star',NEW.item_index,NEW.star) ON CONFLICT(account_id,kind,idx) DO UPDATE SET value=MAX(value,excluded.value); END;
CREATE TRIGGER play_record_equip_star AFTER UPDATE ON equip_items WHEN NEW.star>OLD.star BEGIN INSERT INTO play_record_values(account_id,kind,idx,value) VALUES(NEW.account_id,'equip_star',NEW.item_index,NEW.star) ON CONFLICT(account_id,kind,idx) DO UPDATE SET value=MAX(value,excluded.value); END;
CREATE TRIGGER play_record_soul_grade_new AFTER INSERT ON extension_state WHEN NEW.kind='soul' BEGIN INSERT INTO play_record_values(account_id,kind,idx,value) VALUES(NEW.account_id,'soul_grade',0,COALESCE(json_extract(NEW.data,'$.Grade'),0)) ON CONFLICT(account_id,kind,idx) DO UPDATE SET value=MAX(value,excluded.value); END;
CREATE TRIGGER play_record_soul_grade AFTER UPDATE ON extension_state WHEN NEW.kind='soul' BEGIN INSERT INTO play_record_values(account_id,kind,idx,value) VALUES(NEW.account_id,'soul_grade',0,COALESCE(json_extract(NEW.data,'$.Grade'),0)) ON CONFLICT(account_id,kind,idx) DO UPDATE SET value=MAX(value,excluded.value); END;
CREATE TRIGGER play_record_soul_reinforce_new AFTER INSERT ON extension_state WHEN NEW.kind='soul' BEGIN INSERT INTO play_record_values(account_id,kind,idx,value) VALUES(NEW.account_id,'soul_reinforce',0,COALESCE(json_extract(NEW.data,'$.ReinforceLevel'),0)) ON CONFLICT(account_id,kind,idx) DO UPDATE SET value=MAX(value,excluded.value); END;
CREATE TRIGGER play_record_soul_reinforce AFTER UPDATE ON extension_state WHEN NEW.kind='soul' BEGIN INSERT INTO play_record_values(account_id,kind,idx,value) VALUES(NEW.account_id,'soul_reinforce',0,COALESCE(json_extract(NEW.data,'$.ReinforceLevel'),0)) ON CONFLICT(account_id,kind,idx) DO UPDATE SET value=MAX(value,excluded.value); END;
CREATE TRIGGER play_record_arena_score AFTER UPDATE ON arena_scores WHEN NEW.kind=0 AND NEW.wins>OLD.wins BEGIN INSERT INTO play_record_values(account_id,kind,idx,value) VALUES(NEW.account,'arena_score',0,NEW.score) ON CONFLICT(account_id,kind,idx) DO UPDATE SET value=MAX(value,excluded.value); END;
CREATE TRIGGER play_record_arena_streak AFTER UPDATE ON arena_scores WHEN NEW.kind=0 AND NEW.wins>OLD.wins BEGIN INSERT INTO play_record_values(account_id,kind,idx,value) VALUES(NEW.account,'arena_streak',0,COALESCE(json_extract(NEW.data,'$.SuccessiveWin'),0)) ON CONFLICT(account_id,kind,idx) DO UPDATE SET value=MAX(value,excluded.value); END;
CREATE TRIGGER play_record_arena_wins AFTER UPDATE ON arena_scores WHEN NEW.kind=0 AND NEW.wins>OLD.wins BEGIN INSERT INTO play_record_values(account_id,kind,idx,value) VALUES(NEW.account,'arena_wins',0,NEW.wins-OLD.wins) ON CONFLICT(account_id,kind,idx) DO UPDATE SET value=value+excluded.value; END;
CREATE TRIGGER play_record_arena_losses AFTER UPDATE ON arena_scores WHEN NEW.kind=0 AND NEW.losses>OLD.losses BEGIN INSERT INTO play_record_values(account_id,kind,idx,value) VALUES(NEW.account,'arena_losses',0,NEW.losses-OLD.losses) ON CONFLICT(account_id,kind,idx) DO UPDATE SET value=value+excluded.value; END;
CREATE INDEX heroes_account_index ON heroes(account_id,hero_index);
CREATE INDEX equip_account_inventory ON equip_items(account_id,inventory_type,slot_index);
CREATE INDEX friends_incoming ON friends(friend_account_id,status);
CREATE TABLE response_revisions(scope TEXT NOT NULL,account INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(scope,account));
CREATE TRIGGER response_revision_progression_accounts_INSERT AFTER INSERT ON "accounts" BEGIN INSERT INTO response_revisions(scope,account,revision) SELECT 'progression',NEW."account_id",1 WHERE 1 ON CONFLICT(scope,account) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER response_revision_progression_accounts_UPDATE AFTER UPDATE ON "accounts" WHEN OLD."account_id" IS NOT NEW."account_id" OR OLD."login_id" IS NOT NEW."login_id" OR OLD."created_at" IS NOT NEW."created_at" BEGIN INSERT INTO response_revisions(scope,account,revision) SELECT 'progression',NEW."account_id",1 WHERE 1 ON CONFLICT(scope,account) DO UPDATE SET revision=revision+1;INSERT INTO response_revisions(scope,account,revision) SELECT 'progression',OLD."account_id",1 WHERE (1) AND NOT COALESCE((1) AND OLD."account_id" IS NEW."account_id",0) ON CONFLICT(scope,account) DO UPDATE SET revision=revision+1; END;
