CREATE TRIGGER response_revision_progression_heroes_DELETE AFTER DELETE ON "heroes" BEGIN INSERT INTO response_revisions(scope,account,revision) SELECT 'progression',OLD."account_id",1 WHERE 1 ON CONFLICT(scope,account) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER response_revision_progression_hero_details_INSERT AFTER INSERT ON "hero_details" BEGIN INSERT INTO response_revisions(scope,account,revision) SELECT 'progression',NEW."account_id",1 WHERE 1 ON CONFLICT(scope,account) DO UPDATE SET revision=revision+1; END;
