CREATE TRIGGER currency64_user_INSERT BEFORE INSERT ON user_info WHEN typeof(NEW.gold)!='integer' OR NEW.gold<0 OR typeof(NEW.gem)!='integer' OR NEW.gem<0 OR typeof(NEW.pay_gem)!='integer' OR NEW.pay_gem<0 OR typeof(NEW.pvp_coin)!='integer' OR NEW.pvp_coin<0 OR typeof(NEW.stamina)!='integer' OR NEW.stamina<0 OR typeof(NEW.sword)!='integer' OR NEW.sword<0 OR typeof(NEW.sword2)!='integer' OR NEW.sword2<0 OR typeof(NEW.royal_point)!='integer' OR NEW.royal_point<0 OR typeof(NEW.raid_point)!='integer' OR NEW.raid_point<0 OR typeof(NEW.event_dungeon_point)!='integer' OR NEW.event_dungeon_point<0 OR typeof(NEW.mileage)!='integer' OR NEW.mileage<0 OR typeof(NEW.friendship_point)!='integer' OR NEW.friendship_point<0 OR typeof(NEW.guild_raid_ticket)!='integer' OR NEW.guild_raid_ticket<0 OR typeof(NEW.world_boss_ticket)!='integer' OR NEW.world_boss_ticket<0 OR NEW.gem>9223372036854775807-NEW.pay_gem BEGIN SELECT RAISE(ABORT,'Invalid 64-bit currency balance'); END;
